<script setup lang="ts">
import {can} from './session'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('StaTaskList')

import {ref,onMounted,onUnmounted} from 'vue'
import {api,session} from './session'
import ShipmentDeleteDialog from './ShipmentDeleteDialog.vue'
const props=defineProps<{store?:string}>();const emit=defineEmits(['open-sta'])
const rows=ref<any[]>([]),q=ref(''),store=ref(props.store||''),error=ref(''),page=ref(1),pageSize=ref(25),total=ref(0)
const labels:Record<string,string>={ACTIVE:'进行中',SHIPPED:'已发货',VOIDED:'已作废',ERRORED:'异常',draft:'待创建',queued:'排队中',running:'处理中',ready:'等待下一步',completed:'已完成',failed:'步骤失败',uncertain:'结果待核对',cancelled:'已删除'}
async function load(){try{const result=await api('/sta?'+new URLSearchParams({store:store.value,q:q.value,page:String(page.value),page_size:String(pageSize.value),paginated:'true'}));rows.value=result.rows;total.value=result.total;error.value=''}catch(e){error.value=(e as Error).message}}
const history=ref<any>(null),historyOpen=ref(false)
async function open(row:any){if(row.source!=='amazon'){emit('open-sta',{taskId:row.id,shippingId:row.shipping_id});return}try{history.value=await api('/sta/history/'+encodeURIComponent(row.store)+'/'+encodeURIComponent(row.id));historyOpen.value=true}catch(e){error.value=(e as Error).message}}
const deleteRow=ref<any>(null),deleteDialog=ref(false)
function cancel(row:any){deleteRow.value=row;deleteDialog.value=true}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{load();timer=setInterval(()=>{if(rows.value.some(r=>['running','queued'].includes(r.status)))load()},5000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel"><div class="panel-head"><h2>STA 任务列表</h2><el-button @click="load">刷新任务</el-button></div><form class="sta-list-filters" @submit.prevent="page=1;load()"><el-select v-model="store" clearable placeholder="全部店铺"><el-option v-for="s in session?.stores" :key="s" :value="s"/></el-select><el-input v-model="q" placeholder="搜索任务名称" clearable/><el-button native-type="submit" type="primary">查询</el-button><TableReset table-key="StaTaskList/table-1"/></form><el-alert v-if="error" :title="error" type="error"/><template v-if="true"><el-table border data-width-key="StaTaskList/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="rows"><el-table-column :column-key="'column-1'" :width="tableWidths.width('table-1', 'column-1', undefined)" label="任务 / 入库计划" min-width="250"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{row.name}}</el-button><div class="cell-sub">{{row.source==='amazon'?'亚马逊历史计划（只读）':row.number}}</div><div class="cell-sub">{{row.inbound_plan_id||'尚未创建亚马逊计划'}}</div></template></el-table-column><el-table-column :column-key="'column-2'" label="店铺 / 站点" :width="tableWidths.width('table-1', 'column-2', '150')"><template #default="{row}">{{row.store}} · {{row.country}}</template></el-table-column><el-table-column :column-key="'column-3'" label="状态" :width="tableWidths.width('table-1', 'column-3', '130')"><template #default="{row}"><el-tag :type="['failed','uncertain'].includes(row.status)?'warning':'info'">{{labels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column :column-key="'column-4'" :width="tableWidths.width('table-1', 'column-4', undefined)" label="货件号 / 说明" min-width="260"><template #default="{row}"><div v-for="s in row.shipments" :key="s.shipmentId">{{s.shipmentConfirmationId||'待确认'}} · {{s.destination?.warehouseId}}</div><span class="sta-error">{{row.error}}</span></template></el-table-column><el-table-column :column-key="'column-5'" label="创建时间" :width="tableWidths.width('table-1', 'column-5', '170')"><template #default="{row}">{{new Date(row.created_at).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column :column-key="'column-6'" label="操作" :width="tableWidths.width('table-1', 'column-6', '230')"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{row.source==='amazon'?'查看历史':'详情 / 继续'}}</el-button><el-button v-if="row.source!=='amazon'&&can('fba.sta','operate')" link type="danger" :disabled="['cancelled','queued','running'].includes(row.status)" @click="cancel(row)">删除货件和费用</el-button></template></el-table-column></el-table></template><AppPagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" @change="load()"/><ShipmentDeleteDialog v-if="deleteRow" v-model="deleteDialog" :task-id="deleteRow.id" :name="deleteRow.name" @submitted="load"/><el-drawer v-model="historyOpen" title="亚马逊历史 STA 计划" size="800px"><template v-if="history"><h2>{{history.name}}</h2><p>{{history.inbound_plan_id}} · {{labels[history.status]||history.status}}</p><p class="muted">历史同步记录，仅供查看；不会重新创建或提交货件。</p><h3>关联货件</h3><p v-for="s in history.shipments" :key="s.shipmentId">{{s.shipmentConfirmationId||s.shipmentId}} · {{s.destination?.warehouseId}} · {{s.status}}</p><h3>商品明细</h3><el-table :data="history.items" border><el-table-column prop="msku" label="SKU"/><el-table-column prop="asin" label="ASIN"/><el-table-column prop="fnsku" label="FNSKU"/><el-table-column prop="quantity" label="数量" width="90" align="center"/></el-table></template></el-drawer></section></template>
<style scoped>.sta-list-filters{display:flex;gap:12px;padding:20px}.sta-list-filters .el-select{width:180px}.sta-list-filters .el-input{max-width:400px}.sta-error{color:#b05f2f}</style>
